{"name": "get_usage_examples", "content": {"name": "get_usage_examples", "arguments": {"Qiskit": {"examples": [{"goal": "Prepare a Bell state using Qiskit, which demonstrates the creation of quantum entanglement between two qubits:", "code_snippet": "from qiskit import QuantumCircuit
qc = QuantumCircuit(2, 2)
qc.h(0)
qc.cx(0, 1)
qc.measure([0,1], [0,1])
# This creates a quantum circuit with 2 qubits and 2 classical bits,
# applies Hadamard gate on the first qubit to create superposition,
# then a CNOT to entangle it with the second qubit, and finally measures."}]}, "Cirq": {"examples": [{"goal": "Produce a Bell state in Cirq, which is essential for quantum computing experiments that require maximally entangled qubit pairs:", "code_snippet": "import cirq
qubits = cirq.LineQubit.range(2)
circuit = cirq.Circuit()
circuit.append(cirq.H(qubits[0]))
circuit.append(cirq.CNOT(qubits[0], qubits[1]))
circuit.append(cirq.measure(*qubits))
# This code constructs a Cirq circuit with 2 line qubits,
# adds a Hadamard gate to the first for superposition, a CNOT to entangle with the second,
# and measures the qubits to collapse the state."}]}, "Q#": {"examples": [{"goal": "Create a Bell state using Q#, showcasing its utility for programming foundational quantum algorithms:", "code_snippet": "operation CreateBellState(q1 : Qubit, q2 : Qubit) : Unit {
    H(q1);
    CNOT(q1, q2);
    // Applies the Hadamard gate on the first qubit to generate a superposition,
    // then a CNOT gate between the first and second qubits to create entanglement.
}"}]}}}}
